Here's a complete example:

```java
import javax.swing.*;
import javax.swing.table.DefaultTableModel;

public class JTableInsertExample {
    public static void main(String[] args) {
        String[] columnNames = {"Column 1", "Column 2", "Column 3"};
        Object[][] data = {};
        DefaultTableModel model = new DefaultTableModel(data, columnNames);

        JTable table = new JTable(model);

        JScrollPane scrollPane = new JScrollPane(table);

        JFrame frame = new JFrame("JTable Insert Example");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(scrollPane);
        frame.setSize(400, 300);
        frame.setVisible(true);

        Object[] newRowData = {"Value 1", "Value 2", "Value 3"};
        model.addRow(newRowData);

        int rowIndex = 1;
        Object[] anotherNewRowData = {"Value 4", "Value 5", "Value 6"};
        model.insertRow(rowIndex, anotherNewRowData);

        table.getParent().revalidate();
        table.getParent().repaint();
    }
}
```

