Now, create a new TypeScript file (e.g., `hashring.ts`) and add the following code:

```typescript
import murmurhash3 from 'murmurhash3';
import SortedArray from 'sorted-array';

type Node = {
  id: string;
 weight: number;
};

class HashRing {
 private nodes: SortedArray<Node>;
 private virtualNodes: number;

 constructor(nodes: Node[], virtualNodes: number = 100) {
    this.nodes = new SortedArray<Node>((a, b) => a.id.localeCompare(b.id));
    this.virtualNodes = virtualNodes;

    for (const node of nodes) {
      this.addNode(node);
    }
  }

 private hash(key: string): number {
    return murmurhash3.x86.hash128(key, 'hex') % (2 ** 32);
  }

 private addVirtualNodes(node: Node) {
    for (let i = 0; i < this.virtualNodes; i++) {
      const virtualNodeId = `${node.id}:${i}`;
      this.nodes.add({ id: virtualNodeId, weight: node.weight });
    }
  }

 addNode(node: Node) {
    this.nodes.add(node);
    this.addVirtualNodes(node);
  }

  removeNode(nodeId: string) {
    const node = this.nodes.find((n) => n.id === nodeId);
    if (node) {
      this.nodes.remove(node);

      for (let i = 0; i < this.virtualNodes; i++) {
        const virtualNodeId = `${nodeId}:${i}`;
        this.nodes.remove(this.nodes.find((n) => n.id === virtualNodeId));
      }
    }
  }

  getNode(key: string): Node | null {
    const hash = this.hash(key);
    const node = this.nodes.find((n) => this.hash(n.id) >= hash);

    if (node) {
      return node;
    }

    return this.nodes.first();
  }
}

export default HashRing;
```

