import * as sha256 from 'js-sha3';

class HashRing {
  private replicas: string[];
  private ring: Map<number, string>;

  constructor(replicas: string[], numReplicas: number) {
    this.replicas = replicas;
    this.ring = new Map();

    const hash = (key: string) => sha256.keccak256(key).toString('hex');

    for (let i = 0; i < numReplicas; i++) {
      for (const replica of this.replicas) {
        const key = `${i}:${replica}`;
        const hashValue = hash(key);
        const degree = parseInt(hashValue.slice(0, 8), 16);

        if (!this.ring.has(degree)) {
          this.ring.set(degree, [replica]);
        } else {
          this.ring.get(degree)!.push(replica);
        }
      }
    }
  }

  getReplica(key: string): string {
    const hashValue = sha256.keccak256(key).toString('hex');
    const degree = parseInt(hashValue.slice(0, 8), 16);
    return this.ring.get(degree)![0];
  }
}

// Usage
const replicas = ['replica1', 'replica2', 'replica3'];
const numReplicas = 10;
const hashRing = new HashRing(replicas, numReplicas);

console.log(hashRing.getReplica('key1')); // Output: replica1
console.log(hashRing.getReplica('key2')); // Output: replica2
```

This example creates a hash ring with the given replicas and a specified number of replicas. The `getReplica` method returns the replica responsible for a given key by hashing the key and finding the degree (hash value as an integer) in the ring.

