I'd be happy to help you with some code snippets, but please note that creating a full-fledged real estate app like Magicbricks involves a lot of code and various technologies. Here, I'll provide a simple example of a property listing API using Node.js and Express.js.

First, make sure you have Node.js and npm installed on your machine. Then, create a new directory for your project and navigate to it in your terminal.

1. Initialize a new Node.js project:
```
npm init -y
```

2. Install Express.js and other dependencies:
```
npm install express body-parser cors
```

3. Create a new file named `app.js` and add the following code:

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();

// Middleware
app.use(bodyParser.json());
app.use(cors());

// Dummy data for property listings
let properties = [
  { id: 1, title: 'Property 1', price: 100000, location: 'New York' },
  { id: 2, title: 'Property 2', price: 200000, location: 'Los Angeles' },
  { id: 3, title: 'Property 3', price: 300000, location: 'Chicago' },
];

// API endpoints
app.get('/api/properties', (req, res) => {
  res.json(properties);
});

app.get('/api/properties/:id', (req, res) => {
  const property = properties.find((p) => p.id === parseInt(req.params.id));
  if (!property) return res.status(404).send('Property not found.');
  res.json(property);
});

app.post('/api/properties', (req, res) => {
  const newProperty = {
    id: properties.length + 1,
    title: req.body.title,
    price: req.body.price,
    location: req.body.location,
  };
  properties.push(newProperty);
  res.json(newProperty);
});

app.put('/api/properties/:id', (req, res) => {
  const property = properties.find((p) => p.id === parseInt(req.params.id));
  if (!property) return res.status(404).send('Property not found.');

  property.title = req.body.title;
  property.price = req.body.price;
  property.location = req.body.location;

  res.json(property);
});

app.delete('/api/properties/:id', (req, res) => {
  const property = properties.find((p) => p.id === parseInt(req.params.id));
  if (!property) return res.status(404).send('Property not found.');

  const index = properties.indexOf(property);
  properties.splice(index, 1);

  res.send(property);
});

// Start the server
const port = process.env.PORT || 5000;
app.listen(port, () => console.log(`Server started on port ${port}`));
```

