```javascript
class SimpleSqlBuilder {
  constructor() {
    this.selectFields = [];
    this.fromTable = '';
    this.whereConditions = [];
    this.orderBy = '';
    this.limit = '';
  }

  select(fields) {
    this.selectFields = Array.isArray(fields) ? fields : [fields];
    return this;
  }

  from(table) {
    this.fromTable = table;
    return this;
  }

  where(condition) {
    this.whereConditions.push(condition);
    return this;
  }

  orderBy(field, direction = 'ASC') {
    this.orderBy = `${field} ${direction}`;
    return this;
  }

  limit(limit) {
    this.limit = limit;
    return this;
  }

  build() {
    let query = `SELECT ${this.selectFields.join(', ')} FROM ${this.fromTable}`;

    if (this.whereConditions.length) {
      const conditions = this.whereConditions.map(condition => {
        const [field, operator, value] = condition.split(' ');
        return `${field} ${operator} ${value}`;
      }).join(' AND ');
      query += ` WHERE ${conditions}`;
    }

    if (this.orderBy) {
      query += ` ORDER BY ${this.orderBy}`;
    }

    if (this.limit) {
      query += ` LIMIT ${this.limit}`;
    }

    return query;
  }
}

// Usage example:
const sqlBuilder = new SimpleSqlBuilder();
const query = sqlBuilder
  .select('id', 'name')
  .from('users')
  .where('age > 18')
  .orderBy('name', 'DESC')
  .limit(10)
  .build();

console.log(query);
```

