    {
        static void Main(string[] args)
        {
            // Define the segment as two points
            Vector2 p1 = new Vector2(0, 0);
            Vector2 p2 = new Vector2(1, 1);

            // Define a point to find the distance to
            Vector2 point = new Vector2(0.5, 0.5);

            // Calculate the distance
            float distance = SignedDistance(p1, p2, point);

            // Output the result
