        }

        /// <summary>
        /// Calculates the signed distance from a point to a segment
        /// </summary>
        /// <param name="p1">The first point of the segment</param>
        /// <param name="p2">The second point of the segment</param>
        /// <param name="point">The point to find the distance to</param>
        /// <returns>The signed distance from the point to the segment</returns>
        static float SignedDistance(Vector2 p1, Vector2 p2, Vector2 point)
        {
            // Calculate the vector from p1 to p2
            Vector2 segment = p2 - p1;

            // Calculate the vector from p1 to the point
            Vector2 diff = point - p1;

            // Calculate the projection of the difference vector onto the segment vector
            float prod = Vector2.Dot(diff, segment);

            // If the projection is negative, the point is on the opposite side of the segment
            // In this case, the distance is the length of the segment vector
            if (prod < 0)
            {
                return segment.Length();
            }

            // If the projection is greater than the length of the segment, the point is on the
            // opposite side of the extension of the segment
            // In this case, the distance is the length of the difference vector minus the length
            // of the segment vector
            if (prod > segment.LengthSquared())
            {
                return diff.Length() - segment.Length();
            }

            // Otherwise, the point is on the segment or its extension
            // In this case, the distance is the projection of the difference vector onto the
            // segment vector
            return prod;
        }
    }
}
