Here's a PowerShell script that fulfills your requirements. It uses the `System.Windows.Forms` namespace to display the file selection and save file dialogs. Make sure to run this script with administrative privileges.

```powershell
# Import required .NET namespace
Add-Type -AssemblyName System.Windows.Forms

# Function to display file selection dialog and return selected files
function Get-SelectedFiles {
    $ofd = New-Object System.Windows.Forms.OpenFileDialog
    $ofd.InitialDirectory = [Environment]::GetFolderPath("Desktop")
    $ofd.Filter = "CSV Files (*.csv)|*.csv"
    $ofd.Multiselect = $true

    if ($ofd.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        return $ofd.FileNames
    }
    return @()
}

# Function to display save file dialog and return selected file path
function Get-SaveFilePath {
    $sfd = New-Object System.Windows.Forms.SaveFileDialog
    $sfd.InitialDirectory = [Environment]::GetFolderPath("Desktop")
    $sfd.Filter = "CSV Files (*.csv)|*.csv"
    $sfd.Title = "Save Combined CSV File"

    if ($sfd.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        return $sfd.FileName
    }
    return ""
}

# Get selected CSV files
$selectedFiles = Get-SelectedFiles
if ($selectedFiles.Count -eq 0) {
    Write-Output "No files selected. Exiting."
    exit 1
}

# Get save file path
$saveFilePath = Get-SaveFilePath
if ($saveFilePath -eq "") {
    Write-Output "No file path selected. Exiting."
    exit 1
}

# Combine CSV files and save with header only once
$header = $true
$combinedData = @()
foreach ($file in $selectedFiles) {
    $data = Import-Csv -Path $file
    if ($header) {
        $combinedData += $data | Select-Object -First 1
        $header = $false
    } else {
        $combinedData += $data
    }
}

$combinedData | Export-Csv -Path $saveFilePath -NoTypeInformation

Write-Output "CSV files combined and saved to $saveFilePath"
```

