using System;
using System.Net;
using System.Net.Sockets;

public class IPAddressRange
{
    public IPAddress Start { get; }
    public IPAddress End { get; }

    public IPAddressRange(IPAddress start, IPAddress end)
    {
        if (start == null)
        {
            throw new ArgumentNullException(nameof(start));
        }

        if (end == null)
        {
            throw new ArgumentNullException(nameof(end));
        }

        if (start.AddressFamily != end.AddressFamily)
        {
            throw new ArgumentException("Start and end addresses must have the same address family.");
        }

        Start = start;
        End = end;
    }

    public bool Contains(IPAddress ipAddress)
    {
        if (ipAddress == null)
        {
            throw new ArgumentNullException(nameof(ipAddress));
        }

        if (ipAddress.AddressFamily != Start.AddressFamily)
        {
            return false;
        }

        byte[] startBytes = Start.GetAddressBytes();
        byte[] endBytes = End.GetAddressBytes();
        byte[] ipBytes = ipAddress.GetAddressBytes();

        if (startBytes.Length != endBytes.Length || startBytes.Length != ipBytes.Length)
        {
            throw new ArgumentException("Address families do not match.");
        }

        if (BitConverter.IsLittleEndian)
        {
            Array.Reverse(startBytes);
            Array.Reverse(endBytes);
            Array.Reverse(ipBytes);
        }

        return CompareBytes(startBytes, endBytes, ipBytes) >= 0;
