import org.apache.ignite.cluster.ClusterGroup;
import org.apache.ignite.cluster.ClusterNode;
import org.apache.ignite.events.Event;
import org.apache.ignite.events.EventType;
import org.apache.ignite.lang.IgnitePredicate;

public class NodeGroupManager {

    private Ignite ignite;
    private int currentGroupCount = 0;

    public NodeGroupManager(Ignite ignite) {
        this.ignite = ignite;
        ignite.events().localListen(new IgnitePredicate<Event>() {
            @Override
            public boolean apply(Event evt) {
                if (evt.type() == EventType.EVT_NODE_JOINED) {
                    onNodeJoined((ClusterNode) evt.message());
                } else if (evt.type() == EventType.EVT_NODE_LEFT) {
                    onNodeLeft((ClusterNode) evt.message());
                }
                return true;
            }
        }, EventType.EVT_NODE_JOINED, EventType.EVT_NODE_LEFT);
    }

    private void onNodeJoined(ClusterNode node) {
        currentGroupCount++;
        node.attribute("GROUP", String.valueOf(currentGroupCount));
        updateAffinity();
    }

    private void onNodeLeft(ClusterNode node) {
        int leftGroup = Integer.parseInt(node.attribute("GROUP"));
        ClusterGroup highestGroupNode = ignite.cluster().forAttribute("GROUP", String.valueOf(currentGroupCount));
        if (!highestGroupNode.nodes().isEmpty()) {
            ClusterNode highestNode = highestGroupNode.nodes().iterator().next();
            highestNode.attribute("GROUP", String.valueOf(leftGroup));
        }
        currentGroupCount--;
        updateAffinity();
    }

    private void updateAffinity() {
        // Recalculate affinity and reassign partitions
        // This is a placeholder for the actual logic to update affinity
    }
}
