use sql_parser::{Parser, ParseError, Token, TokenStream};

use std::collections::HashSet;


fn main() -> Result<(), ParseError> {

    let sql = "SELECT * FROM table1 JOIN table2 ON table1.id = table2.id UNION SELECT * FROM table3 UNION ALL SELECT * FROM (SELECT * FROM table4) AS subquery";

    let mut parser = Parser::new();

    let mut tokens: TokenStream = parser.parse(&sql)?;

    let tables: HashSet<String> = extract_tables(&mut tokens)?;

    print_tables(&tables);

    Ok(())

}


fn extract_tables(tokens: &mut TokenStream) -> Result<HashSet<String>, ParseError> {

    let mut tables: HashSet<String> = HashSet::new();

    for token in tokens.into_iter() {

        match token {

            Token::Keyword(Keyword::Table(ref name)) => {

                tables.insert(name.to_string());

            },

            Token::Keyword(Keyword::Subquery(ref name)) => {

                // Handle subqueries by extracting tables from the subquery

                let subquery_tokens = tokens.into_iter().take_while(|t| t != Token::Keyword(Keyword::EndSubquery));

                let subquery_tables: HashSet<String> = extract_tables(&subquery_tokens)?;

                tables.extend(subquery_tables);

            },

            _ => (),

        }

    }

    Ok(tables)

}


fn print_tables(tables: &HashSet<String>) {

    for (i, table) in tables.iter().enumerate() {

        println!("Table {}", i + 1);

        println!("{}", table);

    }

}

```

